#pragma once
// IW4x-32: GENERATED by iw4x32/tools/gen_renderer_status.py from iw4x32/reference/renderer_status.json - do not edit.
// Change the json (or the generator), re-run the generator, and keep
// iw4x32/tools/test_renderer_status.py happy: it regenerates this file and refuses a build
// whose committed copy is not what the json says.
//
// What the renderer actually initialized, as the Options -> Video screens show it. The rules
// below are the whole decision: evidence in, one backend out. Evidence comes from the renderer
// itself (the device it created, what answered d3d9.dll, what the loader loaded), never from
// the OS, the GPU vendor, files on disk or a cvar anyone can set.

namespace Components
{
  // Which renderer is drawing (RendererBackend in the json).
  enum class RendererBackend
  {
    Vulkan = 0, // Native Vulkan (Beta)
    D3D9 = 1, // Direct3D 9
    D3D9Dxvk = 2, // DX9 -> Vulkan (DXVK)
    D3D9DxvkNative = 3, // DX9 -> Vulkan (DXVK-native)
    D3D9Wine = 4, // Direct3D 9 (Wine)
    D3D9WineGL = 5, // Direct3D 9 (Wine/OpenGL)
    Unknown = 6, // Unknown / initializing
  };

  // Evidence bits - what the process could prove about its renderer (RendererEvidence in the json).
  static constexpr unsigned int RS_EV_DEVICE = 0x1; // a D3D9 device was created by the renderer and is alive
  static constexpr unsigned int RS_EV_WINE = 0x2; // ntdll exports wine_get_version: the process runs on Wine (or Proton)
  static constexpr unsigned int RS_EV_DXVK = 0x4; // the D3D9 implementation that answered the device creation is DXVK (the device's own adapter identifier says so)
  static constexpr unsigned int RS_EV_WINED3D = 0x8; // the D3D9 implementation is Wine's wined3d, which draws through OpenGL
  static constexpr unsigned int RS_EV_D3D9_FAILED = 0x10; // the last renderer start failed to create a device; the old status is no longer current
  static constexpr unsigned int RS_EV_NATIVE_LOADER = 0x20; // our own native Linux loader answers d3d9.dll (its query export answered)
  static constexpr unsigned int RS_EV_LOADER_DXVK_NATIVE = 0x40; // that loader loaded DXVK as a native library and hands its device out for d3d9.dll
  static constexpr unsigned int RS_EV_VULKAN_ACTIVE = 0x80; // a direct Vulkan engine backend initialized; no D3D9 device and no translation in the rendering path
  static constexpr unsigned int RS_EV_GL_LOADED = 0x100; // an OpenGL client is loaded in this process - under Wine that is what wined3d draws through

  struct RendererStatusRule
  {
    unsigned int evidence;  // every one of these bits must be set
    unsigned int forbidden; // none of these may be set
    RendererBackend backend;
  };

  // First match wins, so the specific rules come before the general ones.
  static constexpr RendererStatusRule RS_RULES[] = {
    { RS_EV_VULKAN_ACTIVE, RS_EV_DEVICE | RS_EV_DXVK | RS_EV_LOADER_DXVK_NATIVE | RS_EV_WINED3D | RS_EV_WINE | RS_EV_D3D9_FAILED, RendererBackend::Vulkan }, // only a backend with no D3D9 device and no translation in its path may be called Vulkan
    { RS_EV_DEVICE | RS_EV_NATIVE_LOADER | RS_EV_LOADER_DXVK_NATIVE, 0, RendererBackend::D3D9DxvkNative }, // our native loader drew through DXVK: Linux, but the engine is still D3D9
    { RS_EV_DEVICE | RS_EV_DXVK, 0, RendererBackend::D3D9Dxvk }, // DXVK translated the device under Windows / Wine / Proton
    { RS_EV_DEVICE | RS_EV_WINE | RS_EV_WINED3D | RS_EV_GL_LOADED, RS_EV_DXVK, RendererBackend::D3D9WineGL }, // Wine's own D3D9, and the OpenGL client it draws through is loaded in the process
    { RS_EV_DEVICE | RS_EV_WINE, RS_EV_DXVK, RendererBackend::D3D9Wine }, // Wine, but the backend behind the device is not pinned down further
    { RS_EV_DEVICE, RS_EV_WINE | RS_EV_DXVK | RS_EV_LOADER_DXVK_NATIVE | RS_EV_WINED3D, RendererBackend::D3D9 }, // a plain D3D9 device, nothing known to translate it
    { 0, 0, RendererBackend::Unknown }, // nothing proved: before the first device, or after a renderer start that failed
  };

  struct RendererStatusLabel
  {
    RendererBackend backend;
    const char* label; // what the Options -> Video screen shows
  };

  static constexpr RendererStatusLabel RS_LABELS[] = {
    { RendererBackend::Vulkan, "Native Vulkan (Beta)" },
    { RendererBackend::D3D9, "Direct3D 9" },
    { RendererBackend::D3D9Dxvk, "DX9 -> Vulkan (DXVK)" },
    { RendererBackend::D3D9DxvkNative, "DX9 -> Vulkan (DXVK-native)" },
    { RendererBackend::D3D9Wine, "Direct3D 9 (Wine)" },
    { RendererBackend::D3D9WineGL, "Direct3D 9 (Wine/OpenGL)" },
    { RendererBackend::Unknown, "Unknown / initializing" },
  };

  // The native loader's report about its own d3d9.dll - the same struct, field for field, as
  // iw4x32/native/src/renderer_status.h (the test compares the two).
  static constexpr unsigned int RS_QUERY_MAGIC = 0x32525349;
  static constexpr int RS_QUERY_DXVK_CHARS = 64;
  static constexpr char RS_QUERY_NAME[] = "IW4x32_QueryRendererBackend";

  struct RendererBackendReport
  {
    unsigned int size;              // sizeof this struct, both ways
    unsigned int magic;             // RS_QUERY_MAGIC
    unsigned int evidence;          // RS_EV_* bits the loader itself proved
    unsigned int devices;           // D3D9 devices the loader handed out (0 until the renderer is up)
    unsigned int presents;          // frames presented through it
    char dxvk[RS_QUERY_DXVK_CHARS]; // what the loader loaded as DXVK, empty if none
  };

  static_assert(sizeof(RendererBackendReport) == 5 * 4 + RS_QUERY_DXVK_CHARS,
                "the loader reports the struct with a different layout");
}
